import json                                   # standard-library JSON module

PAYLOAD = """
{
  "ietf-interfaces:interface": [
    {"name": "GigabitEthernet1", "description": "Uplink to WAN", "enabled": true},
    {"name": "GigabitEthernet2", "enabled": false},
    {"name": "Loopback0", "description": "Router ID", "enabled": true}
  ]
}
"""

def disabled_interfaces(data):
    """Return the names of administratively disabled interfaces."""
    result = []                                   # empty list
    for intf in data["ietf-interfaces:interface"]:
        if not intf.get("enabled", True):         # missing key -> default True
            result.append(intf["name"])
    return result

if __name__ == "__main__":
    data = json.loads(PAYLOAD)                    # JSON text -> Python dict
    down = disabled_interfaces(data)
    print(f"{len(down)} disabled: {down}")
    data["ietf-interfaces:interface"][1]["enabled"] = True
    print(json.dumps(data, indent=2))             # Python dict -> JSON text

module ietf-interfaces {
  namespace "urn:ietf:params:xml:ns:yang:ietf-interfaces";
  prefix if;

  container interfaces {              // groups related nodes
    list interface {                  // many entries...
      key "name";                     // ...each identified by its name
      leaf name {
        type string;
      }
      leaf description {
        type string;
      }
      leaf type {
        type identityref { base interface-type; }
        mandatory true;
      }
      leaf enabled {
        type boolean;
        default "true";
      }
    }
  }
}

